'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const N = data[idx++];
const Q = data[idx++];

const values = new Array(N + 1).fill(0);
const tree = new Array(N + 1).fill(0);

function add(pos, delta) {
  for (let i = pos; i <= N; i += i & -i) {
    tree[i] += delta;
  }
}

function prefixSum(pos) {
  let sum = 0;
  for (let i = pos; i > 0; i -= i & -i) {
    sum += tree[i];
  }
  return sum;
}

for (let i = 1; i <= N; i++) {
  values[i] = data[idx++];
  add(i, values[i]);
}

const output = [];

for (let i = 0; i < Q; i++) {
  const type = data[idx++];
  const k = data[idx++];

  if (type === 0) {
    const people = data[idx++];
    add(k, people - values[k]);
    values[k] = people;
  } else {
    output.push(String(prefixSum(k)));
  }
}

process.stdout.write(output.join('\n'));
